examples.template:
HStack(spacing: MonarchTokens.Space.space2) {
    MonarchAiConversationHeader(
        title,
        agent: MonarchAiAgentRef(name: {{agent}}),
        model: {{model}},
        onRename: { newTitle in title = newTitle }
    )
    .frame(maxWidth: .infinity)
    MonarchButton({{share.label}}, variant: .{{share.variant|raw}}, size: .{{share.size|raw}}) {}
    Menu({{more.label}}) {
        Button({{more.items.0.label}}) {}
        Button({{more.items.1.label}}, role: .destructive) {}
    }
    .buttonStyle(.monarch(.{{more.variant|raw}}, size: .{{more.size|raw}}))
}

